/// <summary>
/// Extension of class <c>SalesPackingSlipDP</c>
/// </summary>
[ExtensionOf(classStr(SalesPackingSlipDP))]
final class KPMGSalesPackingSlipDP_Extension
{
}

Method.Source:
    /// <summary>
    /// Initializes a sales packing slip header.
    /// </summary>
    /// <returns>
    /// The initialized <c>SalesPackingSlipHeaderTmp</c> sales packing slip header record.
    /// </returns>
    protected SalesPackingSlipHeaderTmp initializeSalesPackingSlipHeader()
    {
        CompanyInfo               companyInfo = CompanyInfo::find();
        SalesPackingSlipHeaderTmp salesPackingSlipHeaderTmp;
        SalesTable                salesTable;
        METCustTable              metCustTable;

        METIndustryKeyTable       metIndustryKeyTbl;
        LogisticsEntityPostalAddressView metLogisticsEntityPostalAddressView;
        InventLocation            metInventLocation;

        salesPackingSlipHeaderTmp                       = next initializeSalesPackingSlipHeader();
        salesTable                                      = SalesTable::find(salesPackingSlipHeaderTmp.SalesId);
        salesPackingSlipHeaderTmp.CompanyEmail          = companyInfo.email();
        salesPackingSlipHeaderTmp.KPMGReturnItemNum     = salesTable.ReturnItemNum;
        salesPackingSlipHeaderTmp.KPMGContactPersonId   = salesTable.contactPersonName();

        Image img = CustTable::metGetCustReportLogo(this.parmCustPackingSlipJour().InvoiceAccount);
        if(img)
        {
            salesPackingSlipHeaderTmp.KPMGCompanyLogo       = img.getData();
        }
        
        salesPackingSlipHeaderTmp.KPMGDeliveryDocumentNo    = this.parmCustPackingSlipJour().PackingSlipId;
        salesPackingSlipHeaderTmp.KPMGCustomerNumber        = this.parmCustPackingSlipJour().InvoiceAccount;
        salesPackingSlipHeaderTmp.KPMGShipDate              = this.parmCustPackingSlipJour().DeliveryDate;
        salesPackingSlipHeaderTmp.METRoute                  = SalesTable::find(this.parmCustPackingSlipJour().SalesId).METRoute;
        salesPackingSlipHeaderTmp.KPMGRouteStop             = int2Str(SalesTable::find(this.parmCustPackingSlipJour().SalesId).METRouteStopNum);
        //salesPackingSlipHeaderTmp.KPMGRouteStop             = SalesTable::find(this.parmCustPackingSlipJour().SalesId).METRouteStop;
        salesPackingSlipHeaderTmp.KPMGDeliveryInstructions  = METSalesTable::findByRefRecId(SalesTable::find(this.parmCustPackingSlipJour().SalesId).RecId).DeliveryInstructions;
        salesPackingSlipHeaderTmp.KPMGCustomerAddress       = DirUtility::replaceAddressTokenLanguage(CustTable::find(this.parmCustPackingSlipJour().InvoiceAccount).statementAddress(), CustTable::find(this.parmCustPackingSlipJour().InvoiceAccount).languageId());
        salesPackingSlipHeaderTmp.METInventLocationName     = InventLocation::find(this.parmCustPackingSlipJour().inventLocationId).Name;

        //Katsuhiro - correcting details to get on industry keys
        select metCustTable where metCustTable.AccountNum == this.parmCustPackingSlipJour().InvoiceAccount
            join metIndustryKeyTbl where metIndustryKeyTbl.IndustryKey == metCustTable.IndustryKey;
        {
            salesPackingSlipHeaderTmp.CompanyName = metIndustryKeyTbl.CompanyName;
            salesPackingSlipHeaderTmp.KPMGCompanyABN = metIndustryKeyTbl.CoRegNum;
            salesPackingSlipHeaderTmp.CompanyPhone = metIndustryKeyTbl.CarrierDocumentPhone;
            salesPackingSlipHeaderTmp.CompanyEmail = metIndustryKeyTbl.CarrierDocumentEmail;
        }

        select metInventLocation where metInventLocation.InventLocationId == salesTable.InventLocationId
            join metLogisticsEntityPostalAddressView where metLogisticsEntityPostalAddressView.EntityLocation == metInventLocation.RecId;
        {
            salesPackingSlipHeaderTmp.CompanyAddress = metLogisticsEntityPostalAddressView.Address;
        }

        //Checking if has multiple saled id
        CustPackingSlipTrans metCustPackingSlipTrans;
        str strSalesID = "";
        
        while select metCustPackingSlipTrans where metCustPackingSlipTrans.PackingSlipId == this.parmCustPackingSlipJour().PackingSlipId
        {
            if(strSalesID == "")
            {
                strSalesID = metCustPackingSlipTrans.OrigSalesId;
            }
            else
            {
                if(strSalesID != metCustPackingSlipTrans.OrigSalesId)
                {
                    salesPackingSlipHeaderTmp.SalesId = "MULTIPLE";
                }
            }
        }

        return salesPackingSlipHeaderTmp;
    }

    /// <summary>
    /// Initializes a sales packing slip line.
    /// </summary>
    /// <param name = "_salesPackingSlipHeaderTmp">
    /// A <c>SalesPackingSlipHeaderTmp</c> record which is the sales packing slip header.
    /// </param>
    /// <param name = "_packingSlipLineSelection">
    /// A <c>SalesPackingSlipDPPackingSlipLineQuerySelection</c> object which the sales packing slip line should be initialized from.
    /// </param>
    /// <returns>
    /// The initialized <c>SalesPackingSlipDetailsTmp</c> sales packing slip line record.
    /// </returns>
    protected SalesPackingSlipDetailsTmp initializeSalesPackingSlipLine(
        SalesPackingSlipHeaderTmp                       _salesPackingSlipHeaderTmp,
        SalesPackingSlipDPPackingSlipLineQuerySelection _packingSlipLineSelection)
    {
        SalesPackingSlipDetailsTmp salesPackingSlipTmp;

        EcoResProduct metEcoResProduct;
        EcoResProductCategory metEcoResProductCategory;
        EcoResCategory metEcoResCategory;
        boolean blnContains;
        UnitOfMeasureConversion metUOMConversion;
        UnitOfMeasure METUnitOfMeasure;
        MetContainerTable tblMetContainerTable;
        METContainerTypeTable tblMetContainerTypeTable;
        

        salesPackingSlipTmp = next initializeSalesPackingSlipLine(_salesPackingSlipHeaderTmp, _packingSlipLineSelection);

        salesPackingSlipTmp.KPMGOrderNo         = _packingSlipLineSelection.parmCustPackingSlipTrans().OrigSalesId;
        salesPackingSlipTmp.KPMGUOM             = _packingSlipLineSelection.parmCustPackingSlipTrans().SalesUnit;
        salesPackingSlipTmp.METName             = EcoResProductTranslation::findByProductLanguage(InventTable::find(salesPackingSlipTmp.ItemId).Product, SystemParameters::getSystemLanguageId()).Name;

        if (salesPackingSlipTmp.KPMGUOM == METConstants::unitcase)
        {
            Qty metCartons    = salesPackingSlipTmp.Qty;
            salesPackingSlipTmp.METCartons += rounddown(metCartons, 1);
        }


        //KEGS, CHEP and LOSCOM count for display
        SalesPackingSlipDetailsTmp metSalesPackingSlipDetailsTmp;
        CustPackingSlipTrans metCustPackingSlipTrans;
        CustPackingSlipJour metCustPackingSlipJour;
        
        while select metCustPackingSlipTrans where metCustPackingSlipTrans.PackingSlipId == _salesPackingSlipHeaderTmp.PackingSlipId
            join metEcoResProduct where metEcoResProduct.DisplayProductNumber == metCustPackingSlipTrans.ItemId
            join metUOMConversion where metUOMConversion.Product == metEcoResProduct.RecId
            join METUnitOfMeasure where METUnitOfMeasure.RecId == metUOMConversion.ToUnitOfMeasure
        {
            if(strUpr(METUnitOfMeasure.Symbol) == "KEGS" || strUpr(METUnitOfMeasure.Symbol) == "KEG")
            {
                select metCustPackingSlipJour where metCustPackingSlipJour.PackingSlipId == _packingSlipLineSelection.parmCustPackingSlipTrans().PackingSlipId;
                {
                    Qty metCartons    = metCustPackingSlipTrans.Qty;
                    salesPackingSlipTmp.METKegs += rounddown(metCartons, 1);
                }
            }
        }

        MetContainerTable metContainerTbl;

        select metCustPackingSlipJour where metCustPackingSlipJour.PackingSlipId == _packingSlipLineSelection.parmCustPackingSlipTrans().PackingSlipId;
        {
            while select metContainerTbl where metContainerTbl.MetShipmentId == metCustPackingSlipJour.METShipmentId
            {
                if(metContainerTbl.ContainerTypeCode == "LOS")
                {
                    Qty metCartons    = metContainerTbl.MetContainerQty;
                    salesPackingSlipTmp.METLoscam += rounddown(metCartons, 1);
                }
                else if(metContainerTbl.ContainerTypeCode == "CHP")
                {
                    Qty metCartons    = metContainerTbl.MetContainerQty;
                    salesPackingSlipTmp.METChep += rounddown(metCartons, 1);
                }
            }
        }

        return salesPackingSlipTmp;
    }
